  ('catalog-teacher-liz-caplan', 'liz-caplan-voice-teacher', 'Liz Caplan', 'Vocal coach for stage and recording performers, with an individual approach to breath, alignment and expression.', 'https://www.lizcaplan.com/about-liz', 'https://www.lizcaplan.com/about-liz', 'Vocal coach', 'published', '2026-11-10'),
  ('catalog-teacher-fernanda-douglas', 'fernanda-douglas-voice-teacher', 'Fernanda Douglas', 'New York City voice coach and music director, listed as an associate at Liz Caplan Vocal Studios.', 'https://www.lizcaplan.com/team-1', 'https://www.lizcaplan.com/team-1', 'Vocal coach', 'published', '2026-11-10');
INSERT INTO instructors (id, slug, name, description, website_url, source_url, professional_title, profile_status, last_verified_at) VALUES
  ('catalog-teacher-rae-covey', 'rae-covey-voice-teacher', 'Rae Covey', 'Voice-coaching associate at Liz Caplan Vocal Studios, supporting performers as they develop their individual voices.', 'https://www.lizcaplan.com/team-1', 'https://www.lizcaplan.com/team-1', 'Vocal coach', 'published', '2026-11-10'),
  ('catalog-teacher-david-sisco', 'david-sisco-voice-teacher', 'David Sisco', 'New York City teaching artist combining vocal technique with interpretation and storytelling in song.', 'https://davidsisco.com/teaching/', 'https://davidsisco.com/teaching/', 'Voice teacher', 'published', '2026-11-10'),
  ('catalog-teacher-mary-setrakian', 'mary-setrakian-voice-teacher', 'Mary Setrakian', 'Private voice instruction offered in New York City and on Zoom; contact the studio for availability.', 'https://marysetrakian.com/newyorkclasses', 'https://marysetrakian.com/newyorkclasses', 'Voice teacher', 'published', '2026-11-10'),
  ('catalog-teacher-deric-rosenblatt', 'deric-rosenblatt-voice-teacher', 'Deric Rosenblatt', 'Individual voice training through Vocal Power, with a studio on Manhattan’s Upper West Side.', 'https://www.vocalpowerllc.com/', 'https://www.vocalpowerllc.com/', 'Vocal coach', 'published', '2026-11-10'),
  ('catalog-teacher-michael-forman', 'michael-forman-voice-teacher', 'Michael Forman', 'Midtown Manhattan vocal coaching for audition preparation, song interpretation, repertoire and role preparation.', 'https://formanvocalcoach.com/', 'https://formanvocalcoach.com/', 'Vocal coach', 'published', '2026-11-10'),
  ('catalog-teacher-sherry-boone', 'sherry-boone-voice-teacher', 'Sherry Boone', 'Brooklyn voice instruction for beginning singers, focused on vocal exercises and applying technique to songs.', 'https://www.sherryboone.com/lessons_with_sherry', 'https://www.sherryboone.com/lessons_with_sherry', 'Voice teacher', 'published', '2026-11-10');
INSERT INTO offerings (id, slug, provider_id, name, description, registration_url, format, price_min, price_max, currency, price_basis, duration_minutes, session_count, schedule_text, audition_required, instruction_mode, source_url, listing_status, origin, last_verified_at) VALUES
  ('catalog-class-bkcm-intro-singing-adults', 'bkcm-intro-singing-adults', 'catalog-provider-bkcm', 'Intro to Singing for Adults — BKCM', 'Adult group singing with Alexis Hightower, exploring breathing, registers, pitch and expression. Published semester tuition; confirm enrollment and fees.', 'https://bkcm.org/class-ensemble/intro-to-singing-for-adults-level-1/', 'in_person', 776, 776, 'USD', 'full_course', 90, NULL, '16-week semester; Wednesday evenings are listed. Confirm current availability with BKCM.', NULL, 'group', 'https://bkcm.org/class-ensemble/intro-to-singing-for-adults-level-1/', 'published', 'seeded', '2026-11-10'),
  ('catalog-class-bkcm-jazz-vocal-lab', 'bkcm-jazz-vocal-lab', 'catalog-provider-bkcm', 'Jazz Vocal Lab — BKCM', 'Adult jazz singing with Annie Chen and piano accompaniment. Experience and placement requirements apply; a foundations section is also offered.', 'https://bkcm.org/class-ensemble/jazz-vocal-lab/', 'in_person', 776, 776, 'USD', 'full_course', 90, NULL, '16-week semester. Confirm section placement, dates and financial aid.', 1, 'group', 'https://bkcm.org/class-ensemble/jazz-vocal-lab/', 'published', 'seeded', '2026-11-10'),
  ('catalog-class-brooklyn-harmonics-vocal-program', 'brooklyn-harmonics-vocal-program', 'catalog-provider-bkcm', 'Brooklyn Harmonics Vocal Program', 'Age-specific vocal ensembles led by Christine Cornell and Jeff Klitz. Auditions, cohorts, tuition and rehearsal arrangements vary.', 'https://bkcm.org/brooklyn-harmonics/', 'in_person', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'group', 'https://bkcm.org/brooklyn-harmonics/', 'published', 'seeded', '2026-11-10'),
  ('catalog-class-brooklyn-conservatory-chorale', 'brooklyn-conservatory-chorale', 'catalog-provider-bkcm', 'Brooklyn Conservatory Chorale', 'Adult choral singing directed by Conrad Chu. Audition required. Published tuition is per semester; annual enrollment is also offered.', 'https://bkcm.org/class-ensemble/brooklyn-conservatory-chorale/', 'in_person', 344, 344, 'USD', 'full_course', NULL, NULL, NULL, 1, 'group', 'https://bkcm.org/class-ensemble/brooklyn-conservatory-chorale/', 'published', 'seeded', '2026-11-10'),
  ('catalog-class-lucy-moses-opera-workshop', 'lucy-moses-opera-workshop', 'catalog-provider-lucy', 'Opera Workshop — Lucy Moses School', 'Adult opera-scene workshop with Judith Barnes, developing musical interpretation, language and stagecraft. Audition required; confirm current or next-session enrollment.', 'https://www.kaufmanmusiccenter.org/lms/class/c19688/', NULL, 605, 605, 'USD', 'full_course', 120, 10, 'Fall 2026 catalog: September 23–December 9.', 1, 'group', 'https://www.kaufmanmusiccenter.org/lms/class/c19688/', 'published', 'seeded', '2026-11-10'),
  ('catalog-class-lucy-moses-sight-singing-intermediate-one', 'lucy-moses-sight-singing-intermediate-one', 'catalog-provider-lucy', 'Sight-Singing: Intermediate I — Lucy Moses School', 'Adult sight-singing with Liz Fleischer, developing interval reading through songs and part-singing. Ask the school about placement.', 'https://www.kaufmanmusiccenter.org/lms/class/c19750/', NULL, 400, 400, 'USD', 'full_course', 60, 10, 'Fall 2026 catalog: October 6–December 15. Confirm remaining or next-session enrollment.', NULL, 'group', 'https://www.kaufmanmusiccenter.org/lms/class/c19750/', 'published', 'seeded', '2026-11-10'),
  ('catalog-class-lucy-moses-sight-singing-intermediate-two', 'lucy-moses-sight-singing-intermediate-two', 'catalog-provider-lucy', 'Sight-Singing: Intermediate II — Lucy Moses School', 'Adult sight-singing with Liz Fleischer, adding chromatic material. Intermediate I or equivalent preparation is a listed prerequisite.', 'https://www.kaufmanmusiccenter.org/lms/class/c19739/', NULL, 400, 400, 'USD', 'full_course', 60, 10, 'Fall 2026 catalog: September 30–December 16. Confirm remaining or next-session enrollment.', NULL, 'group', 'https://www.kaufmanmusiccenter.org/lms/class/c19739/', 'published', 'seeded', '2026-11-10'),
  ('catalog-class-nyja-vocal-jazz-workshops', 'nyja-vocal-jazz-workshops', 'catalog-provider-nyja', 'Vocal Jazz Workshops — New York Jazz Academy', 'Small-group jazz singing, improvisation and interpretation. Manhattan and online options are advertised; confirm the selected section, placement and tuition.', 'https://www.nyjazzacademy.com/programs/vocal/vocal-jazz-workshops/', 'in_person', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'group', 'https://www.nyjazzacademy.com/programs/vocal/vocal-jazz-workshops/', 'published', 'seeded', '2026-11-10'),
  ('catalog-class-92ny-everybody-can-sing', '92ny-everybody-can-sing', 'catalog-provider-92ny', 'Everybody Can Sing — 92NY', 'Beginner singing with Elissa Weiss at 92NY, exploring breathing, pitch and group singing. See the school for upcoming sections.', 'https://www.92ny.org/class/everybody-can-sing', 'in_person', 165, 165, 'USD', 'full_course', 90, NULL, NULL, NULL, 'group', 'https://www.92ny.org/class/everybody-can-sing', 'published', 'seeded', '2026-11-10'),
  ('catalog-class-bloomingdale-broadway-ensemble', 'bloomingdale-broadway-ensemble', 'catalog-provider-bloomingdale', 'Broadway Ensemble — Bloomingdale', 'Musical-theatre ensemble for ages 13–21, including singing, character work and audition preparation. Tuition covers a 17-week semester.', 'https://www.bsmny.org/class/teens/broadway-ensemble/', NULL, 731, 731, 'USD', 'full_course', 75, NULL, NULL, NULL, 'group', 'https://www.bsmny.org/class/teens/broadway-ensemble/', 'published', 'seeded', '2026-11-10'),
  ('catalog-class-bloomingdale-voice-pre-teens', 'bloomingdale-voice-pre-teens', 'catalog-provider-bloomingdale', 'Voice for Pre-Teens — Bloomingdale', 'Group singing for ages 10–13, developing vocal foundations and ensemble skills. The current catalog leaves the instructor unspecified.', 'https://www.bsmny.org/class/children/voice-for-pre-teens/', NULL, 833, 833, 'USD', 'full_course', 60, NULL, '17-week semester. Ask the school about placement and enrollment.', NULL, 'group', 'https://www.bsmny.org/class/children/voice-for-pre-teens/', 'published', 'seeded', '2026-11-10'),
  ('catalog-class-bloomingdale-voice-children', 'bloomingdale-voice-children', 'catalog-provider-bloomingdale', 'Voice for Children — Bloomingdale', 'Group singing for ages 5–9, with warmups, music reading and performances. Instructor and schedule depend on the selected section.', 'https://www.bsmny.org/class/children/voice-for-children-2/', NULL, 833, 833, 'USD', 'full_course', 60, NULL, '17-week semester. Check the official page for sections.', NULL, 'group', 'https://www.bsmny.org/class/children/voice-for-children-2/', 'published', 'seeded', '2026-11-10'),
  ('catalog-class-bloomingdale-intro-singing-adults', 'bloomingdale-intro-singing-adults', 'catalog-provider-bloomingdale', 'Introduction to Singing: Adults — Bloomingdale', 'Adult beginner singing with Christine Browning, including vocal foundations, individual feedback and group singing. Published tuition covers a semester.', 'https://www.bsmny.org/class/adults/introduction-to-singing/', NULL, 918, 918, 'USD', 'full_course', 60, NULL, '17-week semester. Confirm current or next-session availability.', NULL, 'group', 'https://www.bsmny.org/class/adults/introduction-to-singing/', 'published', 'seeded', '2026-11-10');
